            whiteSpace: 'nowrap',
          }}
        >
          <Role role="date">{texts.date}</Role>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// Scene timing lives in meta.ts so metadata and render always agree.
